import { InvalidStorageKeyError } from "./types";

/**
 * Storage keys are relative, slash-separated paths of safe characters.
 * Keys are generated by the application, never taken from user input such as
 * an uploaded file's name. Mirrored in workers/geo-processing/src/trailworker/storage.py.
 */
const SEGMENT = /^[A-Za-z0-9][A-Za-z0-9._-]*$/;
const MAX_KEY_LENGTH = 512;

export function assertValidStorageKey(key: string): void {
  if (key.length === 0 || key.length > MAX_KEY_LENGTH) {
    throw new InvalidStorageKeyError(key, `length must be 1 to ${MAX_KEY_LENGTH}`);
  }
  for (const segment of key.split("/")) {
    if (!SEGMENT.test(segment) || segment === "." || segment === "..") {
      throw new InvalidStorageKeyError(key, `segment "${segment}" is not allowed`);
    }
  }
}

export type StorageArea = "uploads" | "exports";

/** Builds a key such as `uploads/<ownerId>/<fileId>.gpx`. */
export function buildStorageKey(area: StorageArea, ownerId: string, fileId: string, extension: string): string {
  const key = `${area}/${ownerId}/${fileId}.${extension.replace(/^\./, "").toLowerCase()}`;
  assertValidStorageKey(key);
  return key;
}
